_REALTOR_ROLE = "realtor"


def mark_existing_leads_read(apps, schema_editor):
    """
    Every lead that exists WHEN THIS MIGRATION RUNS counts as already seen.

    Without this the feature would launch by telling each realtor that every
    lead they have already worked — closed ones included — is unread. A counter
    whose first reading is wrong is a counter nobody trusts afterwards, so the
    baseline is zero and only genuinely new arrivals ring.

    ⚠ `apps.get_model()`, never a concrete import: the concrete model is
    TODAY's, and would select today's columns against the schema as it stands
    at THIS migration. No `.defer()` either — the historical model has no such
    field and would raise FieldDoesNotExist.
    """
    User = apps.get_model(settings.AUTH_USER_MODEL)
    Lead = apps.get_model("leads", "Lead")
    LeadReadReceipt = apps.get_model("leads", "LeadReadReceipt")

    realtor_ids = list(
        User.objects.filter(role=_REALTOR_ROLE).values_list("id", flat=True)
    )
    if not realtor_ids:
        return

    # Only leads the realtor could actually open are theirs to have "read" —
    # the same scope the counter uses (leads assigned to them). Unassigned
    # leads are invisible to realtors, so there is nothing to mark.
    rows = [
        LeadReadReceipt(lead_id=lead_id, user_id=user_id)
        for user_id in realtor_ids
        for lead_id in Lead.objects.filter(assigned_realtor_id=user_id)
        .values_list("id", flat=True)
    ]
